    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnAConstants), &(mDomainBundleEphemeralA.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnASalts,
                    &(mDomainBundleEphemeralB.mKeySpawnAConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_C(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnAConstants), &(mDomainBundleEphemeralB.mKeySpawnASalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnASalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnAConstants));
    //
    // Domain 4 of 6, key b spawn:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_D(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mKeySpawnBConstants), &(mDomainBundleInbuilt.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralA.mKeySpawnBConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mKeySpawnBConstants), &(mDomainBundleEphemeralA.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mKeySpawnBSalts,
                    &(mDomainBundleEphemeralB.mKeySpawnBConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_D(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mKeySpawnBConstants), &(mDomainBundleEphemeralB.mKeySpawnBSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mKeySpawnBSalts,
                    &(pWorkSpace->mDomainBundle.mKeySpawnBConstants));
    //
    // Domain 5 of 6, twist:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_E(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mTwistConstants), &(mDomainBundleInbuilt.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mTwistSalts,
                    &(mDomainBundleEphemeralA.mTwistConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mTwistConstants), &(mDomainBundleEphemeralA.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mTwistSalts,
                    &(mDomainBundleEphemeralB.mTwistConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_E(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mTwistConstants), &(mDomainBundleEphemeralB.mTwistSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mTwistSalts,
                    &(pWorkSpace->mDomainBundle.mTwistConstants));
    //
    // Domain 6 of 6, seed:
    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    KDF_A_F(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mSeedConstants), &(mDomainBundleInbuilt.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mSeedSalts,
                    &(mDomainBundleEphemeralA.mSeedConstants));

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    KDF_B_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mSeedConstants), &(mDomainBundleEphemeralA.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mSeedSalts,
                    &(mDomainBundleEphemeralB.mSeedConstants));

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    KDF_C_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mSeedConstants), &(mDomainBundleEphemeralB.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(pFarmSalt,
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mSeedSalts,
                    &(pWorkSpace->mDomainBundle.mSeedConstants));
    //
    ////////////////////////////////////////////////////////


    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    // src: [source, nonce]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::SEED_A(PARAMS_SEED);

    //
    // src: [$ice]
    // dst: [$rainbow]
    //
    TwistExpander_Vega_Arx::SEED_B(PARAMS_SEED);

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgD;

    TwistDiffuse::DiffuseWithDomainWords(
        aIceLaneA, aIceLaneB, aIceLaneC, aIceLaneD, // entropy lanes
        aRainbowLaneA, aRainbowLaneB, aRainbowLaneC, aRainbowLaneD,  // input lanes
        aAlchemyLaneA, aAlchemyLaneB, aAlchemyLaneC, aAlchemyLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$alchemy]
    // dst: [$augury]
    //
    TwistExpander_Vega_Arx::SEED_C(PARAMS_SEED);

    //
    // src: [$augury]
    // dst: [$spirit]
    //
    TwistExpander_Vega_Arx::SEED_D(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aAuguryLaneA, aAuguryLaneB, aAuguryLaneC, aAuguryLaneD, // entropy lanes
        aSpiritLaneA, aSpiritLaneB, aSpiritLaneC, aSpiritLaneD,  // input lanes
        aDivinationLaneA, aDivinationLaneB, aDivinationLaneC, aDivinationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$divination]
    // dst: [$psychic]
    //
    TwistExpander_Vega_Arx::SEED_E(PARAMS_SEED);

    //
    // src: [$psychic]
    // dst: [$voodoo]
    //
    TwistExpander_Vega_Arx::SEED_F(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aPsychicLaneA, aPsychicLaneB, aPsychicLaneC, aPsychicLaneD, // entropy lanes
        aVoodooLaneA, aVoodooLaneB, aVoodooLaneC, aVoodooLaneD,  // input lanes
        aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$vapor]
    // dst: [$sonic]
    //
    TwistExpander_Vega_Arx::SEED_G(PARAMS_SEED);

    //
    // src: [$sonic]
    // dst: [$planar]
    //
    TwistExpander_Vega_Arx::SEED_H(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aSonicLaneA, aSonicLaneB, aSonicLaneC, aSonicLaneD, // entropy lanes
        aPlanarLaneA, aPlanarLaneB, aPlanarLaneC, aPlanarLaneD,  // input lanes
        aFrostLaneA, aFrostLaneB, aFrostLaneC, aFrostLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$frost]
    // dst: [$gloom]
    //
    TwistExpander_Vega_Arx::SEED_I(PARAMS_SEED);

    //
    // src: [$gloom]
    // dst: [$lightning]
    //
    TwistExpander_Vega_Arx::SEED_J(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aGloomLaneA, aGloomLaneB, aGloomLaneC, aGloomLaneD, // entropy lanes
        aLightningLaneA, aLightningLaneB, aLightningLaneC, aLightningLaneD,  // input lanes
        aWindLaneA, aWindLaneB, aWindLaneC, aWindLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$wind]
    // dst: [$shadow]
    //
    TwistExpander_Vega_Arx::SEED_K(PARAMS_SEED);

    //
    // src: [$shadow]
    // dst: [$fire]
    //
    TwistExpander_Vega_Arx::SEED_L(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aShadowLaneA, aShadowLaneB, aShadowLaneC, aShadowLaneD, // entropy lanes
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD,  // input lanes
        aKineticLaneA, aKineticLaneB, aKineticLaneC, aKineticLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    TwistExpander_Vega_Arx::SEED_M(PARAMS_SEED);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Vega_Arx::SEED_N(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aEvocationLaneA, aEvocationLaneB, aEvocationLaneC, aEvocationLaneD, // entropy lanes
        aRunicLaneA, aRunicLaneB, aRunicLaneC, aRunicLaneD,  // input lanes
        aAbjurationLaneA, aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Vega_Arx::SEED_O(PARAMS_SEED);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Vega_Arx::SEED_P(PARAMS_SEED);

    TwistDiffuse::DiffuseWithDomainWords(
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD, // entropy lanes
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD,  // input lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$earth]
    // dst: [$crystal]
    //
    TwistExpander_Vega_Arx::SEED_Q(PARAMS_SEED);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main seed loops into destination
    //
    TwistSquash::SquashC(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    *pIngress = aIngress;
    *pCarry = aCarry;
    *pWandererA = aWandererA;
    *pWandererB = aWandererB;
    *pWandererC = aWandererC;
    *pWandererD = aWandererD;
    *pWandererE = aWandererE;
    *pWandererF = aWandererF;
    *pWandererG = aWandererG;
    *pWandererH = aWandererH;
    *pWandererI = aWandererI;
    *pWandererJ = aWandererJ;
    *pWandererK = aWandererK;

    ////////////////////////////////////////////////////////
    //
    // Independent key-row flows
    //
    // Key flow — A / A

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Vega_Arx::KEY_A_A_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_A_B(PARAMS_SEED);

    KeyDiffuse_A_A_A(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_A_A_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_A_D(PARAMS_SEED);

    KeyDiffuse_B_A_A(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_A_A_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_A_IceLaneA, VEGA_KEY_A_A_IceLaneB, VEGA_KEY_A_A_IceLaneC, VEGA_KEY_A_A_IceLaneD, &(pWorkSpace->mKeyBoxA[0U][0]));

    // Key flow — A / B

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Vega_Arx::KEY_A_B_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_B_B(PARAMS_SEED);

    KeyDiffuse_A_A_B(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_A_B_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_B_D(PARAMS_SEED);

    KeyDiffuse_B_A_B(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_A_B_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_B_IceLaneA, VEGA_KEY_A_B_IceLaneB, VEGA_KEY_A_B_IceLaneC, VEGA_KEY_A_B_IceLaneD, &(pWorkSpace->mKeyBoxA[1U][0]));

    // Key flow — A / C

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Vega_Arx::KEY_A_C_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_C_B(PARAMS_SEED);

    KeyDiffuse_A_A_C(pWorkSpace);

    //
    // src: [$rainbow]
    // dst: [$water]
    //
    TwistExpander_Vega_Arx::KEY_A_C_C(PARAMS_SEED);

    //
    // src: [$water]
    // dst: [$vapor]
    //
    TwistExpander_Vega_Arx::KEY_A_C_D(PARAMS_SEED);

    KeyDiffuse_B_A_C(pWorkSpace);

    //
    // src: [$frost]
    // dst: [$ice]
    //
    TwistExpander_Vega_Arx::KEY_A_C_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_C_IceLaneA, VEGA_KEY_A_C_IceLaneB, VEGA_KEY_A_C_IceLaneC, VEGA_KEY_A_C_IceLaneD, &(pWorkSpace->mKeyBoxA[2U][0]));

    // Key flow — A / D

    //
    // src: [$earth, $crystal]
    // dst: [$arcane]
    //
    TwistExpander_Vega_Arx::KEY_A_D_A(PARAMS_SEED);

    //
    // src: [$arcane]
    // dst: [$plasma]
    //
    TwistExpander_Vega_Arx::KEY_A_D_B(PARAMS_SEED);

    KeyDiffuse_A_A_D(pWorkSpace);

    //
