    TwistExpander_Vega_Arx::KEY_A_D_E(PARAMS_SEED);

    TwistSquash::SquashKeyA(VEGA_KEY_A_D_IceLaneA, VEGA_KEY_A_D_IceLaneB, VEGA_KEY_A_D_IceLaneC, VEGA_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

