    TwistSquash::SquashKeyA(VEGA_KEY_B_D_IceLaneA, VEGA_KEY_B_D_IceLaneB, VEGA_KEY_B_D_IceLaneC, VEGA_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

